def _update_posts_with_poll(blog_id, poll_id):
    """Refresh the posts that embed the given poll so the updated vote
    counts are reflected on their outputs."""
    posts_service = get_resource_service("posts")
    for post in get_resource_service("client_posts").find(
        {"blog": blog_id, "particular_type": "post"}
    ):
        for assoc in post_utils.get_associations(post):
            if assoc.get("residRef") == poll_id:
                updated_post = post.copy()
                updated_post["content_updated_date"] = utcnow()
                posts_service.update(post.get("_id"), updated_post, post)
                app.blog_cache.invalidate(blog_id)
